/**
 * Sight parity against the table generated by the game's own code (AC4.1).
 *
 * The table carries no map grids; `maps_cs` rows come from the committed dataset sync output
 * (`src/data/article/maps_cs.json`, the grids the page ships). Every case runs in CI: a missing
 * grid file fails the suite instead of skipping it. The map-independent half (vision cone and
 * range, given the table's own `los`) runs as well.
 *
 * @see packages/specs/specs/10-tactical-arena-article.md § P10-4 (AC4.1)
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { type GridMap, parseRows } from "../../src/lib/grid";
import { canSee, inVisionCone, lineOfSight, smokeTiles } from "../../src/lib/sight";

interface Case {
	readonly kind: string;
	readonly map: string;
	readonly viewer: { r: number; c: number; facing: number };
	readonly target: { r: number; c: number };
	readonly smokes: ReadonlyArray<readonly [number, number]>;
	readonly los: boolean;
	readonly see: boolean;
}
interface Parity {
	readonly verifiedAgainstGame: boolean;
	readonly settings: Record<string, unknown>;
	readonly cases: readonly Case[];
}

const root = join(import.meta.dirname, "../..");
const table = JSON.parse(
	readFileSync(join(root, "tests/fixtures/article/sight_parity.json"), "utf8"),
) as Parity;

function loadMaps(): Map<string, GridMap> {
	const json = JSON.parse(readFileSync(join(root, "src/data/article/maps_cs.json"), "utf8")) as {
		maps: Array<{ name: string; rows: string[] }>;
	};
	return new Map(json.maps.map((m) => [m.name, parseRows(m.rows)]));
}
const maps = loadMaps();

describe("parity table", () => {
	it("has at least 200 cases, verified against the game, with the head's settings", () => {
		expect(table.cases.length).toBeGreaterThanOrEqual(200);
		expect(table.verifiedAgainstGame).toBe(true);
		expect(table.settings["samples"]).toBe(33);
		expect(table.settings["fovDeg"]).toBe(106);
		expect(table.settings["rangeTiles"]).toBe(10);
	});

	it.each(
		table.cases.map((c, i) => [i, c.kind, c] as const),
	)("case %i (%s): see = los && cone && range, from the table's own los", (_i, _k, c) => {
		expect(c.see).toBe(c.los && inVisionCone(c.viewer, c.target));
	});

	it.each(
		table.cases.map((c, i) => [i, c.kind, c] as const),
	)("case %i (%s): lineOfSight and canSee equal the game", (_i, _k, c) => {
		const map = maps.get(c.map);
		if (!map) throw new Error(`no grid for ${c.map}`);
		const smoked = new Set(c.smokes.flatMap((s) => smokeTiles(map, s)));
		const a: [number, number] = [c.viewer.r, c.viewer.c];
		const b: [number, number] = [c.target.r, c.target.c];
		expect(lineOfSight(map, a, b, smoked)).toBe(c.los);
		expect(canSee(map, c.viewer, c.target, smoked)).toBe(c.see);
	});
});
